// @ts-nocheck
import * as React from 'react';
import Tab from '@mui/material/Tab';
import Box from '@mui/material/Box';
import CustomizedMenus from './DDmenu';
import Tabs, { tabsClasses } from '@mui/material/Tabs';
import { useEffect, useState } from 'react';

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

function CustomTabPanel(props: props) {

  const { children, value, index, ...other } = props;
  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`simple-tabpanel-${index}`}
      aria-labelledby={`simple-tab-${index}`}
      {...other}
    >
      {value === index && <Box sx={{ p: 3 }}>{children}</Box>}
    </div>
  );
}



export default function BasicTabs(props: props) {
  const [data, setData] = useState(null);
  const [value, setValue] = React.useState(0);
  useEffect(() => {
      fetch('toBeUsed/productGeneralization.json')
      .then(response => response.json())
      .then(data => setData(data))
      .catch(error => console.error('Error fetching data:', error));
  }, []);


  function a11yProps(index: number) {
    return {
      id: `simple-tab-${index}`,
      'aria-controls': `simple-tabpanel-${index}`,
    };
  }


  const handleChange = (event: React.SyntheticEvent, newValue: number) => {
    setValue(newValue);
  };

  if (!data) {
    return <div>Loading...</div>;
  } 

  return (
    <Box sx={{ width: '100%'}}>
      <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
        <Tabs 
        sx={{
          [`& .${tabsClasses.scrollButtons}`]: {
            '&.Mui-disabled': { opacity: 0.3 },
          },
        }}
      
        variant="scrollable"  scrollButtons value={value} onChange={handleChange} aria-label="basic tabs example">
        {data.map(item => (
            <Tab sx={{ width: '5.8vw'}} label={item.PC} {...a11yProps(item.value)} />
        ))}
        </Tabs>
      </Box>

        <CustomTabPanel value={value} index={0}>
          <CustomizedMenus props = {[data.at(0), props]}/>
        </CustomTabPanel>
        <CustomTabPanel value={value} index={1}>
          <CustomizedMenus props = {[data.at(1), props]}/>
        </CustomTabPanel>
        <CustomTabPanel value={value} index={2}>
          <CustomizedMenus props = {[data.at(2), props]}/>
        </CustomTabPanel>
        <CustomTabPanel value={value} index={3}>
          <CustomizedMenus props = {[data.at(3), props]}/>
        </CustomTabPanel>
        <CustomTabPanel value={value} index={4}>
          <CustomizedMenus props = {[data.at(4),props]}/>
        </CustomTabPanel>
        <CustomTabPanel value={value} index={5}>
          <CustomizedMenus props = {[data.at(5), props]}/>
        </CustomTabPanel>
        <CustomTabPanel value={value} index={6}>
          <CustomizedMenus props = {[data.at(6),props]}/>
        </CustomTabPanel>
        <CustomTabPanel value={value} index={7}>
          <CustomizedMenus props = {[data.at(7),props]}/>
        </CustomTabPanel>
  
    </Box>
  );
}

