// @ts-nocheck
import * as React from 'react';
import AppBar from '@mui/material/AppBar';
import Box from '@mui/material/Box';
import Toolbar from '@mui/material/Toolbar';
import StyledMenu from './DDmenu';
import Stack from '@mui/material/Stack';
import Button from '@mui/material/Button';
import CloseIcon from '@mui/icons-material/Close';

export default function MenuAppBar({props}: {props: MenuBarProps} ) {
  const [auth, setAuth] = React.useState(true);
  const [anchorEl, setAnchorEl] = React.useState<null | HTMLElement>(null);

  // Related to the user picked List of Products
  
  const removeMe = (index: number) => props.setCurrentProducts(props.currentProducts.filter((_, i) => i !== index));

  function ButtonList( {currentProducts}: {currentProducts: string[]} ) {
    return (
      <Stack sx={{marginLeft: 'auto', minWidth: 0,  marginRight: '0', maxWidth:'70vw', overflow:'scroll'}}direction="row" spacing={'20px'}>        
        {props.currentProducts.map((value:string, index:number) => (
          <Button onClick={() => removeMe(index)} sx={{overflow: 'hidden', width:'8vw',textWrap: 'nowrap', mimWidth: '160px'}} variant="contained" startIcon={<CloseIcon />}>
            <div style={{overflow: 'hidden'}} className="productText">
              {value[0]}
            </div>
        </Button>
        ))}
      </Stack>
    );
  }


  return (
    <Box sx={{ flexGrow: 1}}>
      <AppBar sx={{height:'4vh', position: 'fixed', zIndex: 1201, backgroundColor: 'rgb(52, 140, 235)'}}>
      <div  style={{marginLeft:'1vw', marginTop:'1vh'}}><strong>Grocery Price Tracker</strong></div>
      </AppBar>
    </Box>
  );
}