// @ts-nocheck

import * as React from 'react';
import { styled } from '@mui/material/styles';
import Box from '@mui/material/Box';
import Paper from '@mui/material/Paper';
import Grid from '@mui/material/Grid';
import Graph from './Graph'
import { useEffect, useState } from 'react';
const Item = styled(Paper)(({ theme }) => ({
  backgroundColor: '#fff',
  ...theme.typography.body2,
  padding: theme.spacing(1),
  textAlign: 'center',
  color: (theme.vars ?? theme).palette.text.secondary,
  ...theme.applyStyles('dark', {
    backgroundColor: '#1A2027',
  }),
}));

export default function BasicGrid(props:props) {
    const [data, setData] = useState(null);
        const [value, setValue] = React.useState(0);
        useEffect(() => {
            fetch('toBeUsed/normalizedCPI.json')
            .then(response => response.json())
            .then(data => setData(data))
            .catch(error => console.error('Error fetching data:', error));
        }, []);
    const tempProd = props.props.currentProducts
    if (!data){
        return (<div>One Second</div>)
    }


    var newArr = []
    var timeArr = []
    var cpiArr = []
    var j = 0

    for (var i = 0; i < data.length; i++) {
        if (data[i].Date >= tempProd[1][j]) {
            if (data[i].Date < tempProd[1][j+1]){
                if (j > tempProd.length) {
                    break
                }
                if (!data[i].value){
                    break
                }
                cpiArr.push(data[i].value)
                timeArr.push(data[i].Date)
                newArr.push(tempProd[3][j])
            } else{
                j = j+ 1
            }
            
        
        }

        
    }
    
  return (
    <Box sx={{ position:'absolute', right:'5vw', top:'16vh', flexGrow: 1 }}>
      <Grid container spacing={10}>
        <Grid size={8}>
        <Graph  props = {[props, 2]}/>
        </Grid>
        <Grid size={10}>
        <Graph props = {[[newArr, timeArr, cpiArr], 3]}/>
        </Grid>
      </Grid>
    </Box>
  );
}