// @ts-nocheck
import * as React from 'react';
import {ListItemButton, ListItemText, ListItem} from '@mui/material';

import Collapse from '@mui/material/Collapse';
import ExpandLess from '@mui/icons-material/ExpandLess';
import ExpandMore from '@mui/icons-material/ExpandMore';
import { useState  } from 'react';
import Divider from '@mui/material/Divider';
import Grid from './Grid'
export default function NestedList(props: props) {

  const [data, setData] = useState(null);
    const [open, setOpen] = React.useState(false);
    const [item, setItem] = useState(props.props[0])

    const handleClick = (vals) => {
      setOpen(!open);

      fetch('toBeUsed/JSON/' + vals+ '.json')
          .then(response => response.json())
          .then(data => setData(data))
          .catch(error => console.error('Error fetching data:', error));

  
    };

  const CollapsedList = () => {
    if (!data) {
      return <div>Loading...</div>;
    }
      return (
        <Grid props = {[data, props.props[1]]}/>
      )
  }
  return (
    <div>
      <ListItem id={item}>
        <ListItemText primary={item} sx={{ width: '90%' }} />
        <ListItemButton onClick={() => handleClick(item)}>
          {open ? <ExpandLess /> : <ExpandMore />}
        </ListItemButton>
      </ListItem>
      <Divider sx={{ bgcolor: '#d1d8e1' }} />
      <Collapse in={open} timeout="auto" unmountOnExit>
          <CollapsedList />

  

          </Collapse>
      
    </div>
  );
}
