// @ts-nocheck


import * as React from 'react';
import Box from '@mui/material/Box';
import { DataGrid, GridColDef } from '@mui/x-data-grid';
import { useEffect, useState } from 'react';
import Stack from '@mui/material/Stack';

const columns = [
  {
    field:'id'  ,
    headerName: 'Product Name',
    width: 400,
  },
  {
    field: 'Parent Company',
    headerName: 'Parent Company',
    width: 170,
  },
  {
    field: 'Length',
    headerName: 'Years Observed',
    type: 'number',
    width: 150,

  },
  {
    field: 'Price Diff',
    headerName: 'Change in Price',
    type: 'number',
    width: 110,
  },
  {
    field: 'Percent Increase/Yr',
    headerName: 'Percent Increase',
    type: 'number',
    width: 110,
  },
];


export default function Grid(props: props) {
    const [checkboxSelection, setCheckboxSelection] = React.useState(true);
    const [currentProducts, setSelectedRows] = React.useState(props.props[1].props.currentProducts)
    const [data2, setData] = useState(props.props[0]);
    const [link, setLink] = useState('toBeUsed/JSON/' + props + '.json')
    const [open, setOpen] = React.useState(false);
    const [item, setItem] = useState(props)

  const handleRowClick = (
      params, // GridRowParams
      event, // MuiEvent<React.MouseEvent<HTMLElement>>
      details, // GridCallbackDetails
    ) => {
      props.props[1].props.setCurrentProducts([params['id'], params.row['Date'], params.row['Price'], params.row['New Price']])
    };
  
  const arrayColumn = (arr, n) => arr.map(x => x[n]);
  let selectedRows=arrayColumn(currentProducts, 0)
  return (
    <Stack spacing={2} sx={{ width: '100%' }}>
    <Box sx={{ width: '100%' }}>
    <div style={{ display: 'flex', flexDirection: 'column' }}>
      
      <DataGrid
      sx={{
        boxShadow: 2,
        border: 2,
        "& .MuiDataGrid-row:hover": {
      backgroundColor: "#d5d1d1"
        // color: "red"
  },
        borderColor: 'primary.light',
  
      }}
      onRowClick={handleRowClick}      
      rows = {data2}
      disableColumnMenu = {true}
        columns={columns}
        initialState={{
          pagination: {
            paginationModel: {
              pageSize: 10,
            },
          },
        }}
        rowSelectionModel={false}
        pageSizeOptions={[8]}
        
         />
         
      </div>

    </Box>
    </Stack>
  );
}